//! B165: primitive width and signedness are exact in a funcdef signature.
//!
//! The engine side is a committed live-game corpus generated by
//! `scripts/probe_const_handle_funcdef.py --b165-primitive`. The checker side
//! uses the same directional table so neither the `int`/`int64` asymmetry nor
//! either signedness direction can disappear behind one representative row.

use std::collections::BTreeMap;
use std::path::PathBuf;

use openplanet_lsp::config::LspConfig;
use openplanet_lsp::server::diagnostics::compute_diagnostics;
use openplanet_lsp::typedb::TypeIndex;
use tower_lsp::lsp_types::{DiagnosticSeverity, Url};

const PAIRS: &[(&str, &str, &str)] = &[
    ("int-at-int64", "int64", "int"),
    ("int64-at-int", "int", "int64"),
    ("uint-at-uint64", "uint64", "uint"),
    ("uint64-at-uint", "uint", "uint64"),
    ("int-at-uint", "uint", "int"),
    ("uint-at-int", "int", "uint"),
    ("int64-at-uint64", "uint64", "int64"),
    ("uint64-at-int64", "int64", "uint64"),
];

#[derive(Debug)]
struct Row {
    expect: String,
    verdict: String,
    messages: String,
}

fn corpus_rows() -> BTreeMap<String, Row> {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("docs/probes/b165-primitive-funcdef.tsv");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("B165's live-game corpus must read at {path:?}: {e}"));
    let mut rows = BTreeMap::new();
    for line in text.lines() {
        if line.starts_with('#') || line.starts_with("id\t") || line.is_empty() {
            continue;
        }
        let fields: Vec<_> = line.split('\t').collect();
        assert_eq!(fields.len(), 7, "malformed B165 corpus row: {line:?}");
        rows.insert(
            fields[0].to_string(),
            Row {
                expect: fields[2].to_string(),
                verdict: fields[3].to_string(),
                messages: fields[5].to_string(),
            },
        );
    }
    rows
}

fn errors(source: &str, typedb: Option<&TypeIndex>) -> Vec<String> {
    let uri = Url::parse("file:///test/b165.as").expect("test uri");
    compute_diagnostics(&uri, source, &LspConfig::default(), typedb)
        .into_iter()
        .filter(|d| d.severity == Some(DiagnosticSeverity::ERROR))
        .map(|d| d.message)
        .collect()
}

#[test]
fn the_live_oracle_covers_every_requested_direction_and_both_controls() {
    let rows = corpus_rows();
    assert_eq!(rows.len(), 11, "two controls + startnew + eight pairs");
    assert_eq!(
        (
            rows["b165-primitive-ctl-valid"].expect.as_str(),
            rows["b165-primitive-ctl-valid"].verdict.as_str()
        ),
        ("ACCEPT", "ACCEPT"),
    );
    assert_eq!(
        (
            rows["b165-primitive-ctl-bogus"].expect.as_str(),
            rows["b165-primitive-ctl-bogus"].verdict.as_str()
        ),
        ("REJECT", "REJECT"),
    );
    for (id, _, _) in PAIRS {
        assert!(
            rows.contains_key(&format!("b165-primitive-{id}")),
            "missing requested direction {id}: {rows:#?}"
        );
    }
}

fn assert_all_question_rows_are_unknown_rejects(rows: &BTreeMap<String, Row>) {
    let mut ids = vec!["b165-primitive-startnew-int-int64".to_string()];
    ids.extend(
        PAIRS
            .iter()
            .map(|(id, _, _)| format!("b165-primitive-{id}")),
    );
    assert_eq!(ids.len(), 9, "startnew + eight directional rows");

    for id in ids {
        let row = rows
            .get(&id)
            .unwrap_or_else(|| panic!("missing required B165 question row {id}: {rows:#?}"));
        assert_eq!(
            row.expect, "UNKNOWN",
            "{id} must remain a question row; changing expect must not hide an engine verdict"
        );
        assert_eq!(row.verdict, "REJECT", "engine accepted {id}: {row:?}");
        assert_ne!(
            row.messages, "-",
            "a rejected row must preserve the engine's diagnostic: {id}"
        );
    }
}

#[test]
fn the_engine_rejects_every_primitive_mismatch_including_real_startnew() {
    let rows = corpus_rows();
    assert_all_question_rows_are_unknown_rejects(&rows);
    assert!(
        rows["b165-primitive-startnew-int-int64"]
            .messages
            .contains("No matching signatures to 'startnew"),
        "the real built-in seam must be measured directly"
    );
}

#[test]
fn changing_a_question_expectation_cannot_hide_its_reject_verdict() {
    let mut rows = corpus_rows();
    rows.get_mut("b165-primitive-int-at-int64")
        .expect("mutation target must exist")
        .expect = "ACCEPT".to_string();
    let caught = std::panic::catch_unwind(|| assert_all_question_rows_are_unknown_rejects(&rows));
    assert!(
        caught.is_err(),
        "the oracle guard must fail if a required question row stops being UNKNOWN"
    );
}

#[test]
fn the_checker_matches_the_measured_primitive_matrix() {
    let exact = errors(
        "funcdef void FD(int64 v);\nvoid F(int64 v) {}\n\
         void Use() { FD@ h = F; if (h is null) return; }",
        None,
    );
    assert!(exact.is_empty(), "the exact control must bind: {exact:?}");

    for (id, slot_ty, handler_ty) in PAIRS {
        let src = format!(
            "funcdef void FD({slot_ty} v);\n\
             void F({handler_ty} v) {{}}\n\
             void Use() {{ FD@ h = F; if (h is null) return; }}"
        );
        assert!(
            errors(&src, None)
                .iter()
                .any(|m| m.starts_with("Can't implicitly convert")),
            "checker accepted the engine-rejected direction {id}:\n{src}"
        );
    }

    let fixtures = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/typedb");
    let typedb = TypeIndex::load(
        &fixtures.join("OpenplanetCore.json"),
        &fixtures.join("OpenplanetNext.json"),
    )
    .expect("typedb fixtures must load");
    let startnew = errors(
        "void H(int v) {}\nvoid Use() { startnew(H, 1); }",
        Some(&typedb),
    );
    assert!(
        startnew
            .iter()
            .any(|m| m.starts_with("No matching signatures to 'startnew")),
        "checker must reject the measured real startnew shape: {startnew:?}"
    );
}
